#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>
#include <nb.h>

#define MAX_BRICKS 36

struct PartBrick {
  int id;
  const char *part_name;
  int x, y, z;
  int sx, sz;
  int color; /* 1=Red, 2=Yellow, 4=Blue, 5=LightGrey, 6=DarkGrey, 7=White, 8=TransYellow */
  int step;
  double ex, ey, ez; /* Normalized exploded-view vector */
};

static struct PartBrick parts[MAX_BRICKS];
static int n_parts = 0;
static int adj[MAX_BRICKS][MAX_BRICKS];
static int indeg[MAX_BRICKS];
static int mirror_of[MAX_BRICKS];   /* the same part on the other side, or -1 */

int footprints_overlap(const struct PartBrick *a, const struct PartBrick *b) {
  int ox = (a->x < b->x + b->sx) && (b->x < a->x + a->sx);
  int oz = (a->z < b->z + b->sz) && (b->z < a->z + a->sz);
  return ox && oz;
}

void add_part(const char *name, int x, int y, int z, int sx, int sz, int color) {
  if (n_parts >= MAX_BRICKS) return;
  struct PartBrick cand = { n_parts, name, x, y, z, sx, sz, color, 0, 0, 0, 0 };
  for (int i = 0; i < n_parts; i++) {
    if (parts[i].y == y && footprints_overlap(&parts[i], &cand)) {
      fprintf(stderr, "Clash on layer %d between '%s' and '%s'\n", y, parts[i].part_name, name);
      exit(2);
    }
  }
  parts[n_parts++] = cand;
}

int main(void) {
  int model = (int)nb_get_int("inst_model", 0);
  int max_per_step = (int)nb_get_int("inst_max_per_step", 4);
  if (max_per_step < 2) max_per_step = 2;

  if (model == 0) {
    /* Space Cruiser (Blue fuselage, Grey wings, Trans-Yellow cockpit, Red thrusters) */
    /* Layer 0: Keel & Landing Skids */
    add_part("Plate 2x6 Keel",      3, 0, 5, 6, 2, 6);
    add_part("Skid 1x4 Left",       2, 0, 2, 4, 1, 6);
    add_part("Skid 1x4 Right",      2, 0, 9, 4, 1, 6);
    /* Layer 1: Main Delta Wing Span & Fuselage Floor */
    add_part("Wing Plate 4x4 L",    2, 1, 1, 4, 4, 5);
    add_part("Wing Plate 4x4 R",    2, 1, 7, 4, 4, 5);
    add_part("Center Spine 2x8",    2, 1, 5, 8, 2, 5);
    add_part("Nose Plate 2x3",     10, 1, 5, 3, 2, 4);
    /* Layer 2: Blue Hull & Wingtip Lasers */
    add_part("Hull Brick 2x6",      3, 2, 5, 6, 2, 4);
    add_part("Side Pod 1x4 L",      3, 2, 3, 4, 1, 4);
    add_part("Side Pod 1x4 R",      3, 2, 8, 4, 1, 4);
    add_part("Wingtip Laser 1x2 L", 4, 2, 1, 2, 1, 1);
    add_part("Wingtip Laser 1x2 R", 4, 2,10, 2, 1, 1);
    add_part("Nose Cone 2x3",       9, 2, 5, 3, 2, 4);
    /* Layer 3: Trans-Yellow Canopy & Yellow Space Insignia */
    add_part("Canopy 2x4 Trans-Y",  7, 3, 5, 4, 2, 8);
    add_part("Insignia Brick 2x2",  5, 3, 5, 2, 2, 2);
    add_part("Aft Engine Mount 2x2",3, 3, 5, 2, 2, 4);
    add_part("Rear Thruster L",     2, 2, 4, 1, 1, 1);
    add_part("Rear Thruster R",     2, 2, 7, 1, 1, 1);
    /* Layer 4 & 5: Vertical Tail Fin & Radar Dish */
    add_part("Tail Fin Base 2x2",   3, 4, 5, 2, 2, 4);
    add_part("Tail Fin Crest 2x2",  3, 5, 5, 2, 2, 2);
    add_part("Radar Mast 1x2",      5, 4, 5, 1, 2, 7);
  } else {
    /* Medieval Watchtower & Gate */
    add_part("Base Foundation 2x6 L", 2, 0, 2, 6, 2, 6);
    add_part("Base Foundation 2x6 R", 2, 0, 8, 6, 2, 6);
    add_part("Pillar 2x2 FL",         6, 1, 2, 2, 2, 5);
    add_part("Pillar 2x2 FR",         6, 1, 8, 2, 2, 5);
    add_part("Pillar 2x2 BL",         2, 1, 2, 2, 2, 5);
    add_part("Pillar 2x2 BR",         2, 1, 8, 2, 2, 5);
    add_part("Wall 2x4 Left",         3, 2, 2, 4, 2, 5);
    add_part("Wall 2x4 Right",        3, 2, 8, 4, 2, 5);
    add_part("Gate Arch 2x8",         5, 3, 2, 2, 8, 5);
    add_part("Rear Bridge 2x8",       3, 3, 2, 2, 8, 6);
    add_part("Parapet Floor 4x8",     3, 4, 2, 4, 8, 6);
    add_part("Battlement 2x2 FL",     5, 5, 2, 2, 2, 5);
    add_part("Battlement 2x2 FR",     5, 5, 8, 2, 2, 5);
    add_part("Battlement 2x2 BL",     3, 5, 2, 2, 2, 5);
    add_part("Battlement 2x2 BR",     3, 5, 8, 2, 2, 5);
    add_part("Signal Brazier 2x2",    4, 5, 5, 2, 2, 1);
  }

  /* Pair each part with its mirror image across the model's centre line (the
     same part, layer and x, reflected in z), so a step can build both sides. */
  int zmin = 999, zmax = -999;
  for (int i = 0; i < n_parts; i++) {
    if (parts[i].z < zmin) zmin = parts[i].z;
    if (parts[i].z + parts[i].sz > zmax) zmax = parts[i].z + parts[i].sz;
  }
  int mirror_pairs = 0;
  for (int i = 0; i < n_parts; i++) {
    mirror_of[i] = -1;
    for (int j = 0; j < n_parts; j++) {
      if (j != i && parts[j].y == parts[i].y && parts[j].x == parts[i].x &&
          parts[j].sx == parts[i].sx && parts[j].sz == parts[i].sz && parts[j].color == parts[i].color &&
          parts[j].z == zmin + zmax - parts[i].z - parts[i].sz) {
        mirror_of[i] = j;
        if (i < j) mirror_pairs++;
      }
    }
  }

  memset(adj, 0, sizeof adj);
  memset(indeg, 0, sizeof indeg);

  /* Build Vertical Insertion & Gravity Support DAG:
     If brick B overlaps brick A in (x,z) and B.y > A.y, then A -> B */
  int dag_edges = 0;
  for (int i = 0; i < n_parts; i++) {
    for (int j = 0; j < n_parts; j++) {
      if (i == j) continue;
      if (parts[j].y > parts[i].y && footprints_overlap(&parts[i], &parts[j])) {
        if (!adj[i][j]) {
          adj[i][j] = 1;
          indeg[j]++;
          dag_edges++;
        }
      }
    }
  }

  /* Topological Step Planner (Kahn's algorithm grouped by layer & symmetry) */
  int placed[MAX_BRICKS] = {0};
  int placed_count = 0;
  int step_num = 0;

  while (placed_count < n_parts) {
    step_num++;
    int batch[MAX_BRICKS], bcount = 0;

    /* Find lowest unplaced layer among ready nodes so steps build bottom-up */
    int min_y = 999;
    for (int i = 0; i < n_parts; i++) {
      if (!placed[i] && indeg[i] == 0 && parts[i].y < min_y) min_y = parts[i].y;
    }

    /* Take ready parts on that layer, keeping mirror pairs together: a pair that
       won't fit in this step waits for the next one. */
    int in_batch[MAX_BRICKS] = {0};
    for (int i = 0; i < n_parts && bcount < max_per_step; i++) {
      if (placed[i] || in_batch[i] || indeg[i] != 0 || parts[i].y != min_y) continue;
      int m = mirror_of[i];
      int pair = m >= 0 && !placed[m] && !in_batch[m] && indeg[m] == 0 && parts[m].y == min_y;
      if (pair && bcount + 2 > max_per_step && bcount > 0) continue;
      batch[bcount++] = i;
      in_batch[i] = 1;
      if (pair && bcount < max_per_step) {
        batch[bcount++] = m;
        in_batch[m] = 1;
      }
    }
    /* Fallback if any ready node was on another layer */
    if (bcount == 0) {
      for (int i = 0; i < n_parts && bcount < max_per_step; i++) {
        if (!placed[i] && indeg[i] == 0) batch[bcount++] = i;
      }
    }

    for (int k = 0; k < bcount; k++) {
      int u = batch[k];
      placed[u] = 1;
      parts[u].step = step_num;
      placed_count++;
      for (int v = 0; v < n_parts; v++) {
        if (adj[u][v]) indeg[v]--;
      }
    }
  }

  /* Compute centroid and exploded-view vectors */
  double cx = 0, cy = 0, cz = 0;
  for (int i = 0; i < n_parts; i++) {
    cx += parts[i].x + parts[i].sx * 0.5;
    cy += parts[i].y;
    cz += parts[i].z + parts[i].sz * 0.5;
  }
  cx /= n_parts; cy /= n_parts; cz /= n_parts;

  for (int i = 0; i < n_parts; i++) {
    double dx = (parts[i].x + parts[i].sx * 0.5) - cx;
    double dz = (parts[i].z + parts[i].sz * 0.5) - cz;
    parts[i].ex = dx * 0.35;
    parts[i].ey = (parts[i].step - 1) * 0.85 + parts[i].y * 0.3;
    parts[i].ez = dz * 0.35;
  }

  printf("=== Topological Instruction Step Planner ===\n");
  printf("Total Parts: %d | Support/Occlusion DAG Edges: %d | Mirror Pairs: %d | Generated Steps: %d\n\n",
         n_parts, dag_edges, mirror_pairs, step_num);

  for (int s = 1; s <= step_num; s++) {
    printf("Step %d:\n", s);
    for (int i = 0; i < n_parts; i++) {
      if (parts[i].step == s) {
        printf("  + [%-18s] at (x=%2d, y=%d, z=%2d) size %dx%d\n",
               parts[i].part_name, parts[i].x, parts[i].y, parts[i].z,
               parts[i].sx, parts[i].sz);
      }
    }
  }

  static char json[32768];
  int pos = 0;
  pos += snprintf(json + pos, sizeof(json) - pos,
    "{\"totalSteps\":%d,\"dagEdges\":%d,\"cx\":%.2f,\"cz\":%.2f,\"parts\":[",
    step_num, dag_edges, cx, cz);
  for (int i = 0; i < n_parts; i++) {
    pos += snprintf(json + pos, sizeof(json) - pos,
      "%s{\"id\":%d,\"name\":\"%s\",\"x\":%d,\"y\":%d,\"z\":%d,"
      "\"sx\":%d,\"sz\":%d,\"color\":%d,\"step\":%d,"
      "\"ex\":%.3f,\"ey\":%.3f,\"ez\":%.3f}",
      i ? "," : "",
      parts[i].id, parts[i].part_name,
      parts[i].x, parts[i].y, parts[i].z,
      parts[i].sx, parts[i].sz, parts[i].color, parts[i].step,
      parts[i].ex, parts[i].ey, parts[i].ez);
  }
  pos += snprintf(json + pos, sizeof(json) - pos, "]}");
  nb_set_json("instruction_book", json);
  return 0;
}
